INSERT INTO "battle" ("id", "slug", "author_id", "title", "context", "category_id", "tags", "created_at", "deadline")
SELECT v.id, v.slug, v.author, v.title, v.context, 'other', v.tags::jsonb, v.created_at, v.deadline FROM (VALUES
  ('seed_b3_t1', 'adMqdxhd', 'seed_vu_36', 'My dad''s a Republican and I''m a Democrat. He wants to come for Christmas and my bf says he''ll leave if politics comes up. Invite him?', 'We haven''t spent a holiday together in 2 years', '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '760 minutes', now() - interval '760 minutes' + interval '107 hours'),
  ('seed_b3_t2', '4GcmYrpe', 'seed_vu_159', 'I''m the only conservative in my family and my sister uninvited me from her birthday after an argument. Show up anyway with a gift or let it go?', 'She was my maid of honor lol', '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '603 minutes', now() - interval '603 minutes' + interval '110 hours'),
  ('seed_b3_t3', 'FKU2GRCR', 'seed_b3u_17', 'Got laid off Tuesday. Tell my parents now or wait till I find something?', 'They''re already stressed about money and my mom will panic', '{"seed":{"batch":"b3","topic":"jobs","voice":"F"}}', now() - interval '597 minutes', now() - interval '597 minutes' + interval '115 hours'),
  ('seed_b3_t4', 'Fp4AXCgV', 'seed_vu_50', 'Rent is going up $310 in January. Move 40 min further out or eat it?', 'Commute would be an hour each way', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '2975 minutes', now() - interval '2975 minutes' + interval '116 hours'),
  ('seed_b3_t5', '7k8qiP2c', 'seed_vu_81', 'My bf spends $60 a week on DoorDash while we''re "saving for a house." Ok who''s right?', 'He says he works late and is too tired to cook', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '1142 minutes', now() - interval '1142 minutes' + interval '113 hours'),
  ('seed_b3_t6', 'y8jB5QCH', 'seed_vu_43', 'My manager said AI will "change our team" next year. Start applying now or wait to see if I get cut?', '6 years here and I''m good at my job', '{"seed":{"batch":"b3","topic":"jobs","voice":"F"}}', now() - interval '844 minutes', now() - interval '844 minutes' + interval '107 hours'),
  ('seed_b3_t7', '4UiWMCDE', 'seed_tu_12', 'My in-laws vote the opposite way and always start on it at Sunday dinner. My husband says just ignore it. Who''s right?', NULL, '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '2846 minutes', now() - interval '2846 minutes' + interval '119 hours'),
  ('seed_b3_t8', 'EcpuGtGQ', 'seed_tu_7', 'Friends want a $1,400 cabin weekend. I have $900 in savings total. Say I can''t or swipe the card?', NULL, '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '3462 minutes', now() - interval '3462 minutes' + interval '106 hours'),
  ('seed_b3_t9', 'GRLab5Ef', 'seed_vu_22', 'Partner''s been out of work 5 months. Is it wrong that I''m starting to resent paying for everything?', 'He''s applying, I see it, but still', '{"seed":{"batch":"b3","topic":"jobs","voice":"F"}}', now() - interval '2320 minutes', now() - interval '2320 minutes' + interval '101 hours'),
  ('seed_b3_t10', 'R9zAbaRE', 'seed_b3u_22', 'Everything costs so much. Push our wedding a year to save, or courthouse now and party later?', NULL, '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '857 minutes', now() - interval '857 minutes' + interval '100 hours'),
  ('seed_b3_t11', 'EcAcccGr', 'seed_vu_67', 'I''m a Republican and my girlfriend''s family are all hardcore Democrats. Meeting them at Thanksgiving. Keep my mouth shut or be honest if they ask?', 'Her mom already asked who I voted for over text', '{"seed":{"batch":"b3","topic":"politics","voice":"M"}}', now() - interval '2517 minutes', now() - interval '2517 minutes' + interval '110 hours'),
  ('seed_b3_t12', 'UjQGGsn3', 'seed_vu_142', 'My mom shares political memes in the family group chat every single morning. Leave the chat or tell her to stop?', 'My aunt already left', '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '2034 minutes', now() - interval '2034 minutes' + interval '113 hours'),
  ('seed_b3_t13', '4Kms47bz', 'seed_b3u_14', 'My brother and I haven''t talked since we fought about the election. His baby is due in March. Reach out first?', 'I miss him. I just don''t want to fight again', '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '1242 minutes', now() - interval '1242 minutes' + interval '119 hours'),
  ('seed_b3_t14', 'LcRhpGW4', 'seed_vu_109', 'My dad wants to give a toast at my wedding and I know he''ll slip something political in. Let him or skip the toast?', 'Half my fiancée''s family votes the other way', '{"seed":{"batch":"b3","topic":"politics","voice":"M"}}', now() - interval '3557 minutes', now() - interval '3557 minutes' + interval '103 hours'),
  ('seed_b3_t15', '9PxqWUgP', 'seed_b3u_8', 'My husband and I vote differently and our 16 year old asked who''s right. Answer honestly or tell her to decide herself?', NULL, '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '1225 minutes', now() - interval '1225 minutes' + interval '112 hours'),
  ('seed_b3_t16', '6hdPwUE4', 'seed_vu_92', 'Grandpa said something about my girlfriend''s politics at dinner and she wants an apology before she comes back. Ask him to apologize?', 'He''s 84 and I love him to death', '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '2816 minutes', now() - interval '2816 minutes' + interval '106 hours'),
  ('seed_b3_t17', 'jTXMzJvf', 'seed_vu_93', 'Family rule for Christmas: no politics at the table, $5 in a jar every time someone breaks it. Genius or will it make it worse?', 'My uncle says he''ll bring a twenty', '{"seed":{"batch":"b3","topic":"politics","voice":"N"}}', now() - interval '544 minutes', now() - interval '544 minutes' + interval '111 hours'),
  ('seed_b3_t18', '5uHA7Rpx', 'seed_vu_44', 'My parents vote one way and I vote the other and now they won''t help with the down payment they promised. Fight it or drop it?', 'They literally said "we don''t fund people who vote like that"', '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '1127 minutes', now() - interval '1127 minutes' + interval '106 hours'),
  ('seed_b3_t19', 'BVFVUWqa', 'seed_vu_119', 'Company just did layoffs and I survived. Now I''m doing 2 people''s work for the same pay. Ask for a raise or keep my head down?', NULL, '{"seed":{"batch":"b3","topic":"jobs","voice":"F"}}', now() - interval '2925 minutes', now() - interval '2925 minutes' + interval '119 hours'),
  ('seed_b3_t20', 'HheQeFDJ', 'seed_vu_65', 'Been job hunting 7 months. Take a retail job to pay rent or keep holding out for something in my field?', 'I have a marketing degree and $14k in loans', '{"seed":{"batch":"b3","topic":"jobs","voice":"F"}}', now() - interval '2289 minutes', now() - interval '2289 minutes' + interval '105 hours'),
  ('seed_b3_t21', 'fUhycNcD', 'seed_tu_25', 'Wife wants me to go back to school for nursing since my warehouse job might get automated. I''m 34. Do it?', 'Two years of school and we''d be on one income', '{"seed":{"batch":"b3","topic":"jobs","voice":"M"}}', now() - interval '1374 minutes', now() - interval '1374 minutes' + interval '117 hours'),
  ('seed_b3_t22', 'VyBzPPCf', 'seed_vu_88', 'My best friend got laid off and asked me to put in a word at my company. She''s honestly not great at her job. Do I?', NULL, '{"seed":{"batch":"b3","topic":"jobs","voice":"F"}}', now() - interval '3524 minutes', now() - interval '3524 minutes' + interval '114 hours'),
  ('seed_b3_t23', 'KdRfm4mh', 'seed_b3u_25', 'Severance is 3 months of pay. Take a trip I''ve always wanted or save every penny?', 'Trip would be about $2k', '{"seed":{"batch":"b3","topic":"jobs","voice":"F"}}', now() - interval '1968 minutes', now() - interval '1968 minutes' + interval '119 hours'),
  ('seed_b3_t24', 'G8HUAJB4', 'seed_vu_130', 'New job offer pays $8k less but feels way safer from layoffs. Take it?', 'My company has had 3 rounds of cuts this year', '{"seed":{"batch":"b3","topic":"jobs","voice":"F"}}', now() - interval '2291 minutes', now() - interval '2291 minutes' + interval '112 hours'),
  ('seed_b3_t25', 'YfgLqWHf', 'seed_b3u_26', 'Lost my job and haven''t told my girlfriend yet. It''s been 2 weeks. Am I wrong?', 'I''ve been leaving the house at 8 like nothing happened', '{"seed":{"batch":"b3","topic":"jobs","voice":"M"}}', now() - interval '2606 minutes', now() - interval '2606 minutes' + interval '103 hours'),
  ('seed_b3_t26', 'EnKMAbiH', 'seed_vu_11', 'My sister keeps asking to borrow money and never pays it back. She wants $400 for rent. Say no this time?', 'She owes me about $1,800 total', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '372 minutes', now() - interval '372 minutes' + interval '112 hours'),
  ('seed_b3_t27', 'XYw8Zcav', 'seed_b3u_23', 'We split rent 50/50 but he makes twice what I do. Should it be by income instead? Who''s right?', 'He says 50/50 is fair because we use the place equally', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '1038 minutes', now() - interval '1038 minutes' + interval '114 hours'),
  ('seed_b3_t28', '9mDMLWP3', 'seed_b3u_24', 'Groceries for 2 of us are $230 a week now. Is meal prepping every Sunday worth it or is that my whole weekend gone?', NULL, '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '706 minutes', now() - interval '706 minutes' + interval '104 hours'),
  ('seed_b3_t29', 'MSEAbXfi', 'seed_b3u_11', 'I have $6k in credit card debt and my friends want me in their destination wedding. Say yes and add to it, or bow out?', 'Flights alone are $700', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '2590 minutes', now() - interval '2590 minutes' + interval '116 hours'),
  ('seed_b3_t30', 'uM9XSXZU', 'seed_vu_120', 'Girlfriend wants to keep separate bank accounts after we get married. I want one joint account. Who''s right?', NULL, '{"seed":{"batch":"b3","topic":"money","voice":"M"}}', now() - interval '157 minutes', now() - interval '157 minutes' + interval '114 hours'),
  ('seed_b3_t31', 'HNjEJwrK', 'seed_vu_125', 'My mom asked me to co-sign her car loan. My credit is the only good thing I have going for me. Do it?', NULL, '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '3565 minutes', now() - interval '3565 minutes' + interval '111 hours'),
  ('seed_b3_t32', 'YXiJechP', 'seed_vu_13', 'Do I tell my friends I can only do potluck dinners now instead of restaurants, or keep faking that I''m fine?', 'Last dinner out was $85 with tip and I had a salad', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '2643 minutes', now() - interval '2643 minutes' + interval '107 hours'),
  ('seed_b3_t33', 'uiYBaLZs', 'seed_b3u_20', 'Christmas budget is tight. Tell the family we''re doing a $25 secret santa instead of gifts for everyone?', 'There are 14 of us', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '2467 minutes', now() - interval '2467 minutes' + interval '111 hours'),
  ('seed_b3_t34', '6k6tYpLs', 'seed_b3u_7', 'Everyone says a recession is coming. Keep putting $300 a month into my 401k or build up my savings first?', 'I have about $1,100 in savings', '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '3581 minutes', now() - interval '3581 minutes' + interval '100 hours'),
  ('seed_b3_t35', 'g9WBK7Z2', 'seed_b3u_27', 'We wanted to start trying for a baby next year but daycare is $1,900 a month here. Wait or go for it anyway?', 'I''m 31', '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '601 minutes', now() - interval '601 minutes' + interval '103 hours'),
  ('seed_b3_t36', 'ghcTrScF', 'seed_vu_42', 'Thinking about moving back home with my parents for a year to save. I''m 28. Embarrassing or smart?', 'Rent is $1,650 for a one bedroom', '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '1153 minutes', now() - interval '1153 minutes' + interval '115 hours'),
  ('seed_b3_t37', 'REkbzJQS', 'seed_vu_147', 'Prices are insane. Skip our anniversary trip this year or go anyway because life is short?', 'It''s our 5th', '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '2368 minutes', now() - interval '2368 minutes' + interval '106 hours'),
  ('seed_b3_t38', 'aZjb3QeH', 'seed_b3u_10', 'House prices dropped a little near us. Buy now or wait for them to drop more?', 'Rates are still around 6.5%', '{"seed":{"batch":"b3","topic":"economy","voice":"M"}}', now() - interval '2228 minutes', now() - interval '2228 minutes' + interval '111 hours'),
  ('seed_b3_t39', 'eMWfUW3N', 'seed_b3u_3', 'My husband wants to cancel all our streaming to save money. I want to keep one. Who''s right?', 'We have 5 right now lol', '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '560 minutes', now() - interval '560 minutes' + interval '116 hours'),
  ('seed_b3_t40', 'DF5bJFUA', 'seed_vu_116', 'Gas and groceries are killing us. Sell my car and share his, or keep both?', 'We work 20 minutes apart', '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '656 minutes', now() - interval '656 minutes' + interval '100 hours'),
  ('seed_b3_t41', 'aApeiPsk', 'seed_b3u_12', 'Is it rude to ask wedding guests to chip in for their own drinks now that everything costs double?', 'Open bar quote was $9,000', '{"seed":{"batch":"b3","topic":"economy","voice":"N"}}', now() - interval '2974 minutes', now() - interval '2974 minutes' + interval '103 hours'),
  ('seed_b3_t42', 'PwnGgpUr', 'seed_b3u_5', 'Our landlord is selling and our new rent would be $500 more. Stay or move in with my in-laws for 6 months?', 'My MIL is nice but she reorganizes my stuff', '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '571 minutes', now() - interval '571 minutes' + interval '115 hours'),
  ('seed_b3_p1', 'NavVTfde', 'seed_vu_24', 'We can afford one of these. $1,750 studio downtown or $1,450 two bedroom by my job?', 'All my friends live downtown', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '649 minutes', now() - interval '649 minutes' + interval '109 hours'),
  ('seed_b3_p2', 'qe3PGjnJ', 'seed_vu_106', 'Car died. Used 2017 sedan for $11k or finance a new one at $480 a month?', NULL, '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '2142 minutes', now() - interval '2142 minutes' + interval '118 hours'),
  ('seed_b3_p3', 'i75swkKB', 'seed_vu_89', 'Hosting both families for Thanksgiving and they vote differently. Our place or book a restaurant so everyone behaves?', 'My dad and his stepdad already had one blowup in July', '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '3586 minutes', now() - interval '3586 minutes' + interval '104 hours'),
  ('seed_b3_p4', 'Hd9v8NRF', 'seed_b3u_2', 'Wedding budget is $12k. Backyard at my parents'' or the cheapest venue we found?', 'The venue alone would eat $7k', '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '1285 minutes', now() - interval '1285 minutes' + interval '119 hours'),
  ('seed_b3_p5', 'YxLj5YUy', 'seed_b3u_15', 'Switch to the cheap grocery store across town or keep going to the nice one by my place?', 'I did the math and it''d save me about $60 a week', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '2207 minutes', now() - interval '2207 minutes' + interval '119 hours'),
  ('seed_b3_p6', 'GUuHhAEB', 'seed_b3u_18', 'Keep my remote job or take the in-office one that pays $9k more?', 'The office is 35 min each way', '{"seed":{"batch":"b3","topic":"jobs","voice":"F"}}', now() - interval '1288 minutes', now() - interval '1288 minutes' + interval '102 hours'),
  ('seed_b3_p7', 'gFcGmHxj', 'seed_b3u_6', 'Money''s tight this year. $90 real tree or a $30 tiny one for the table?', 'We have a 2 year old who will 100% pull it over', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '3396 minutes', now() - interval '3396 minutes' + interval '109 hours'),
  ('seed_b3_p8', 'i4AamWjS', 'seed_vu_122', 'Gas is killing me. Trade my old truck for a used plug-in hybrid?', 'I drive 60 miles a day for work', '{"seed":{"batch":"b3","topic":"money","voice":"M"}}', now() - interval '3380 minutes', now() - interval '3380 minutes' + interval '119 hours'),
  ('seed_b3_p9', '8NLR9jyY', 'seed_tu_13', 'Couch is falling apart. $1,800 sectional on a payment plan or a $200 one from Marketplace?', NULL, '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '1947 minutes', now() - interval '1947 minutes' + interval '110 hours'),
  ('seed_b3_p10', 'vLNhgpV5', 'seed_b3u_16', 'We can do one trip this year. Beach rental 3 hours away or a week at my parents'' for free?', 'My parents have a pool and will babysit lol', '{"seed":{"batch":"b3","topic":"economy","voice":"F"}}', now() - interval '2933 minutes', now() - interval '2933 minutes' + interval '101 hours'),
  ('seed_b3_p11', 'Tccndg6A', 'seed_b3u_4', 'Lease is up. Renew our nice place at $2,300 or move to the older one for $1,750?', 'No dishwasher and the bathroom is from 1985', '{"seed":{"batch":"b3","topic":"money","voice":"F"}}', now() - interval '1078 minutes', now() - interval '1078 minutes' + interval '100 hours'),
  ('seed_b3_p12', '4mKvKJMS', 'seed_b3u_1', 'Haven''t talked to my brother since a politics fight. Meet him at a bar or invite him over to my place?', 'My husband says neutral ground is better', '{"seed":{"batch":"b3","topic":"politics","voice":"F"}}', now() - interval '2805 minutes', now() - interval '2805 minutes' + interval '115 hours'),
